/**
 *
 * DataTableRowExpansion is a component that conditionally renders expanded content for a row inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableRowExpansion
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseDataTableExpansionEvent } from '@primereact/types/headless/datatable';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
import type { DataTableRowInstance } from './DataTableRow.types';
/**
 * Defines passthrough(pt) options type in DataTableRowExpansion component.
 */
export type DataTableRowExpansionPassThroughType<E> = PassThroughType<DataTableRowExpansionInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableRowExpansion component.
 */
export interface DataTableRowExpansionPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableRowExpansionPassThroughType<React.HTMLAttributes<HTMLTableRowElement>>;
}
/**
 * Defines valid properties in DataTableRowExpansion component.
 */
export interface DataTableRowExpansionProps extends BaseComponentProps<DataTableRowExpansionInstance, unknown, DataTableRowExpansionPassThrough, 'tr'> {
}
/**
 * Defines valid state in DataTableRowExpansion component.
 */
export interface DataTableRowExpansionState {
}
/**
 * Defines the methods and properties exposed by DataTableRowExpansion component.
 */
export interface DataTableRowExpansionExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
    /**
     * The DataTableRow component instance.
     */
    row: DataTableRowInstance | undefined | null;
}
/**
 * Instance of DataTableRowExpansion component.
 */
export type DataTableRowExpansionInstance = ComponentInstance<DataTableRowExpansionProps, DataTableRowExpansionState, DataTableRowExpansionExposes>;
/**
 * Event re-exported from the headless layer so consumers can import it from the
 * primitive/UI barrel instead of reaching into headless. Mirrors `UseDataTableExpansionEvent`.
 */
export interface DataTableExpansionEvent extends UseDataTableExpansionEvent {
}
